const dialog=document.querySelector('#workspace-dialog');
document.querySelector('.account-button')?.addEventListener('click',()=>location.href='account.html');
document.querySelector('.dialog-close')?.addEventListener('click',()=>dialog.close());
dialog?.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});
const reel=document.querySelector('#showreel');
if(reel){const toggle=document.querySelector('#reel-toggle');let userPaused=matchMedia('(prefers-reduced-motion: reduce)').matches;const names={motion:'Every frame matters',type:'Make it move',story:'Новый ракурс'};function sync(){toggle.textContent=reel.paused?'Смотреть ▶':'Пауза Ⅱ';toggle.setAttribute('aria-label',reel.paused?'Воспроизвести видео':'Остановить видео')}reel.addEventListener('play',sync);reel.addEventListener('pause',sync);toggle.addEventListener('click',()=>{userPaused=!reel.paused;if(reel.paused)reel.play().catch(sync);else reel.pause()});if(userPaused){reel.autoplay=false;reel.pause()}sync();document.querySelectorAll('[data-reel]').forEach(button=>button.addEventListener('click',()=>{const key=button.dataset.reel;reel.src=`assets/demo-${key}.mp4`;reel.poster=`assets/demo-${key}.jpg`;reel.setAttribute('aria-label',names[key]+', демонстрационный ролик');document.querySelector('#reel-name').textContent=names[key];document.querySelectorAll('[data-reel]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));reel.load();if(!userPaused)reel.play().catch(sync);sync()}));new IntersectionObserver(([entry])=>{if(!entry.isIntersecting)reel.pause();else if(!userPaused)reel.play().catch(sync)},{threshold:.15}).observe(reel);document.addEventListener('visibilitychange',()=>{if(document.hidden)reel.pause();else if(!userPaused)reel.play().catch(sync)})}
document.querySelectorAll('[data-filter]').forEach(button=>button.addEventListener('click',()=>{const f=button.dataset.filter;document.querySelectorAll('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));document.querySelectorAll('[data-category]').forEach(card=>{card.hidden=f!=='Все'&&card.dataset.category!==f;if(card.hidden)card.querySelector('video').pause()})}));
document.querySelector('#brief-form')?.addEventListener('submit',e=>{e.preventDefault();const f=e.currentTarget;if(!f.reportValidity())return;const data=new FormData(f);const text=`Бриф / Video Maker Every Thing\n\nПроект: ${data.get('project')}\nФормат: ${data.get('format')}\nЗадача: ${data.get('task')}\nУслуги: ${data.getAll('service').join(', ')||'Не выбраны'}\n`;const url=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='video-maker-brief.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);document.querySelector('#brief-status').textContent='Бриф подготовлен к скачиванию. Заказ никуда не отправлялся.'});

const demoDialog=document.querySelector('#demo-dialog');
if(demoDialog){const v=demoDialog.querySelector('video');['#open-demo','#film-play'].forEach(s=>document.querySelector(s)?.addEventListener('click',()=>{demoDialog.showModal();v.play().catch(()=>{})}));demoDialog.querySelector('.demo-close').addEventListener('click',()=>demoDialog.close());demoDialog.addEventListener('close',()=>v.pause());}
